<script lang="ts">import type { ConnectionCheck, Resource } from '../../lib/api'; import { kubernetesAccessModeLabel } from './resourceWorkflow'; export let resource:Resource; export let resourceCheck:ConnectionCheck|null|undefined; export let mcpServerName=''; export let formatDate:(v:string)=>string; const tools=['kubernetes_cluster_info','kubernetes_api_resources','kubernetes_namespaces','kubernetes_nodes','kubernetes_pods','kubernetes_workloads','kubernetes_services','kubernetes_configmaps','kubernetes_ingresses','kubernetes_events','kubernetes_pod_logs','kubernetes_resource_get','kubernetes_health']; $: agent=String(resource.subtype??'').toLowerCase()==='agent';</script>
<div class="provider-resource-details docker-resource-details"><div class="provider-resource-meta"><div><span>接入方式</span><strong class:agent>{kubernetesAccessModeLabel(agent?'agent':'direct')}</strong></div><div><span>连接端点</span><strong>{agent ? mcpServerName || '关联 MCPServer' : String(resource.config?.server ?? '默认 kubeconfig')}</strong></div><div><span>工具数量</span><strong>{tools.length} 个</strong></div><div><span>最新更新</span><strong>{formatDate(resource.updated_at)}</strong></div><div class="provider-resource-connection"><span>连接状态</span><strong>{resourceCheck ? resourceCheck.status === 'succeeded' ? `正常 · ${resourceCheck.latency_ms} ms` : '连接异常' : '尚未测试'}</strong>{#if resourceCheck?.status === 'failed'}<small>{resourceCheck.message}</small>{/if}</div></div><div class="provider-resource-models mcp-resource-tools"><div class="provider-resource-models-heading"><strong>工具列表</strong><span>{tools.length} 个</span></div>{#each tools as tool}<div class="provider-resource-model-row mcp-resource-tool-row"><div><strong>{tool}</strong></div></div>{/each}</div></div>
